import{_ as n,C as o,c,o as t,a6 as a,G as r}from"./chunks/framework.BY05barL.js";const l="/ucasal-ssoo-estudio/assets/14-programa-proceso.BALluHG_.png",d="/ucasal-ssoo-estudio/assets/14-programa-proceso-threads.DZkAu9xL.png",f=JSON.parse('{"title":"Programas y Procesos","description":"","frontmatter":{},"headers":[],"relativePath":"unidad1/programas-procesos.md","filePath":"unidad1/programas-procesos.md"}'),p={name:"unidad1/programas-procesos.md"};function u(m,e,h,g,P,_){const s=o("ProgramProcessThreadsDemo"),i=o("ProcessStatesDemo");return t(),c("div",null,[e[0]||(e[0]=a('<h1 id="programas-y-procesos" tabindex="-1">Programas y Procesos <a class="header-anchor" href="#programas-y-procesos" aria-label="Permalink to &quot;Programas y Procesos&quot;">​</a></h1><h2 id="diferencias-entre-programa-y-proceso" tabindex="-1">Diferencias entre Programa y Proceso <a class="header-anchor" href="#diferencias-entre-programa-y-proceso" aria-label="Permalink to &quot;Diferencias entre Programa y Proceso&quot;">​</a></h2><p><img src="'+l+'" alt="Proceso y Programa"></p><h3 id="programa" tabindex="-1">Programa <a class="header-anchor" href="#programa" aria-label="Permalink to &quot;Programa&quot;">​</a></h3><p>Un programa es una entidad estática que existe en el almacenamiento secundario:</p><ul><li>Archivo ejecutable (código binario)</li><li>No tiene identificador, estado, recursos ni padre</li><li>Es una secuencia de instrucciones</li><li>Permanece inactivo hasta que se ejecuta</li></ul><h3 id="proceso" tabindex="-1">Proceso <a class="header-anchor" href="#proceso" aria-label="Permalink to &quot;Proceso&quot;">​</a></h3><p>Un proceso es una entidad dinámica que representa la ejecución de un programa:</p><ul><li>Programa en ejecución (cargado en memoria)</li><li>Tiene identificador, estado, recursos y padre</li><li>Tiene un contador de programa que indica la siguiente instrucción a ejecutar</li><li>Tiene un espacio de direcciones en memoria</li><li>Tiene una pila para almacenar variables locales y direcciones de retorno</li><li>Tiene un conjunto de registros del procesador</li></ul><h2 id="programa-proceso-y-threads" tabindex="-1">Programa, Proceso y Threads <a class="header-anchor" href="#programa-proceso-y-threads" aria-label="Permalink to &quot;Programa, Proceso y Threads&quot;">​</a></h2><p>Los threads (hilos) son unidades de ejecución más ligeras dentro de un proceso:</p><p><img src="'+d+'" alt="Programa, Proceso y Threads"></p><p>La siguiente animación recorre la imagen paso a paso: desde el programa en disco hasta el thread que ejecuta la CPU.</p>',13)),r(s),e[1]||(e[1]=a('<h3 id="caracteristicas-de-los-threads" tabindex="-1">Características de los Threads <a class="header-anchor" href="#caracteristicas-de-los-threads" aria-label="Permalink to &quot;Características de los Threads&quot;">​</a></h3><ul><li>Comparten el mismo espacio de direcciones del proceso</li><li>Tienen su propio contador de programa</li><li>Tienen su propia pila</li><li>Comparten recursos del proceso (archivos abiertos, variables globales, etc.)</li><li>Son más eficientes para la creación y cambio de contexto que los procesos</li></ul><h2 id="estados-de-un-proceso" tabindex="-1">Estados de un Proceso <a class="header-anchor" href="#estados-de-un-proceso" aria-label="Permalink to &quot;Estados de un Proceso&quot;">​</a></h2><p>Un proceso puede encontrarse en diferentes estados durante su ciclo de vida:</p><ol><li><strong>Nuevo</strong>: el proceso fue creado, pero el SO todavía no lo admitió</li><li><strong>Listo</strong>: puede ejecutarse, pero espera que el planificador lo elija</li><li><strong>En ejecución</strong>: está usando la CPU en ese instante</li><li><strong>Bloqueado</strong>: espera un evento externo (E/S, señal, etc.)</li><li><strong>Terminado</strong>: el proceso finalizó su ejecución</li></ol>',5)),r(i),e[2]||(e[2]=a('<h2 id="creacion-de-procesos" tabindex="-1">Creación de Procesos <a class="header-anchor" href="#creacion-de-procesos" aria-label="Permalink to &quot;Creación de Procesos&quot;">​</a></h2><p>En sistemas tipo UNIX, los procesos se crean mediante la llamada al sistema <code>fork()</code>:</p><ol><li>El proceso padre llama a <code>fork()</code></li><li>El sistema operativo crea una copia del proceso padre</li><li>El proceso hijo recibe un identificador único (PID)</li><li>Ambos procesos continúan ejecutándose desde el punto donde se llamó a <code>fork()</code></li></ol><p>Para ejecutar un programa diferente, el proceso hijo puede llamar a <code>exec()</code>.</p>',4))])}const b=n(p,[["render",u]]);export{f as __pageData,b as default};
